def generate_opus_image(prompt,out_path):
    cfg=json.load(open('/Users/grant/.openclaw/openclaw.json')); prov=cfg['models']['providers']['openai']; key=prov['apiKey']; base=prov['baseUrl'].rstrip('/')
    # Use required custom model on configured endpoint; try Images API first, then Responses API.
    payload={'model':'opus-image-1.5','prompt':prompt,'n':1,'size':'1536x1024','response_format':'b64_json'}
    with tempfile.NamedTemporaryFile('w',delete=False) as f: json.dump(payload,f); fn=f.name
    try: r=subprocess.run(['curl','-sS','-m','300',base+'/images/generations','-H',f'Authorization: Bearer {key}','-H','Content-Type: application/json','--data-binary','@'+fn],capture_output=True,text=True)
    finally: os.unlink(fn)
    if r.returncode==0:
        try:
            obj=json.loads(r.stdout); item=obj.get('data',[{}])[0]
            if item.get('b64_json'): out_path.write_bytes(base64.b64decode(item['b64_json'])); return {'status':'pass','endpoint':'images/generations','model':'opus-image-1.5','bytes':out_path.stat().st_size}
        except Exception: pass
    payload={'model':'opus-image-1.5','input':prompt,'tools':[{'type':'image_generation','size':'1536x1024','quality':'high'}]}
    with tempfile.NamedTemporaryFile('w',delete=False) as f: json.dump(payload,f); fn=f.name
    try: r2=subprocess.run(['curl','-sS','-m','300',base+'/responses','-H',f'Authorization: Bearer {key}','-H','Content-Type: application/json','--data-binary','@'+fn],capture_output=True,text=True)
    finally: os.unlink(fn)
    if r2.returncode: raise RuntimeError(r2.stderr[:500])
    resp=json.loads(r2.stdout)
    for o in resp.get('output',[]):
        if o.get('type')=='image_generation_call' and o.get('result'):
            out_path.write_bytes(base64.b64decode(o['result'])); return {'status':'pass','endpoint':'responses','model':'opus-image-1.5','response_id':resp.get('id'),'bytes':out_path.stat().st_size}
    raise RuntimeError('no image result '+r.stdout[:500]+' '+r2.stdout[:500])
